1	/** Trial exact JSON codec: inert values, no semantic admission authority. */
2	export type Json = null | boolean | bigint | string | Json[] | { [key: string]: Json };
3	export const MAX_BYTES = 4 * 1024 * 1024;
4	export const MAX_DEPTH = 32;
5	const MIN_INTEGER = -(1n << 63n);
6	const MAX_INTEGER = (1n << 64n) - 1n;
7	const encoder = new TextEncoder();
8	export class JsonError extends Error {}
9	const fail = (message: string): never => { throw new JsonError(message); };
10	
11	function scalarString(value: string): void {
12	  for (const ch of value) {
13	    const cp = ch.codePointAt(0)!;
14	    if (cp >= 0xd800 && cp <= 0xdfff) fail("UNICODE_SCALAR_REQUIRED");
15	  }
16	}
17	
18	export function utf8Compare(a: string, b: string): number {
19	  const left = encoder.encode(a), right = encoder.encode(b);
20	  for (let i = 0; i < Math.min(left.length, right.length); i++) {
21	    if (left[i] !== right[i]) return left[i]! < right[i]! ? -1 : 1;
22	  }
23	  return left.length - right.length;
24	}
25	
26	export function parseExact(raw: Uint8Array): Json {
27	  if (!(raw instanceof Uint8Array)) fail("BYTE_INPUT_REQUIRED");
28	  if (raw.length > MAX_BYTES) fail("BYTE_LIMIT");
29	  let text: string;
30	  try { text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(raw); }
31	  catch { return fail("INVALID_UTF8"); }
32	  let offset = 0;
33	  const space = () => { while (offset < text.length && " \t\r\n".includes(text[offset]!)) offset++; };
34	  const string = (): string => {
35	    const start = offset++;
36	    let escaped = false;
37	    while (offset < text.length) {
38	      const ch = text[offset++]!;
39	      if (!escaped && ch === '"') {
40	        let value: string;
41	        try { value = JSON.parse(text.slice(start, offset)) as string; }
42	        catch { return fail("INVALID_STRING"); }
43	        scalarString(value);
44	        return value;
45	      }
46	      if (escaped) escaped = false;
47	      else if (ch === "\\") escaped = true;
48	    }
49	    return fail("UNTERMINATED_STRING");
50	  };
51	  const value = (depth: number): Json => {
52	    space();
53	    const ch = text[offset];
54	    if (ch === '"') return string();
55	    if (ch === "[" || ch === "{") {
56	      if (depth >= MAX_DEPTH) fail("DEPTH_LIMIT");
57	      offset++; space();
58	      if (ch === "[") {
59	        const result: Json[] = [];
60	        if (text[offset] === "]") { offset++; return result; }
61	        while (true) {
62	          result.push(value(depth + 1)); space();
63	          if (text[offset] === "]") { offset++; return result; }
64	          if (text[offset++] !== ",") return fail("ARRAY_DELIMITER");
65	        }
66	      }
67	      const result: { [key: string]: Json } = Object.create(null);
68	      if (text[offset] === "}") { offset++; return result; }
69	      while (true) {
70	        space(); if (text[offset] !== '"') return fail("OBJECT_KEY");
71	        const key = string();
72	        if (Object.hasOwn(result, key)) fail("DUPLICATE_KEY");
73	        space(); if (text[offset++] !== ":") return fail("OBJECT_COLON");
74	        result[key] = value(depth + 1); space();
75	        if (text[offset] === "}") { offset++; return result; }
76	        if (text[offset++] !== ",") return fail("OBJECT_DELIMITER");
77	      }
78	    }
79	    for (const [token, result] of [["true", true], ["false", false], ["null", null]] as const) {
80	      if (text.startsWith(token, offset)) { offset += token.length; return result; }
81	    }
82	    const match = /^-?(?:0|[1-9][0-9]*)/.exec(text.slice(offset));
83	    if (!match) return fail("INVALID_VALUE");
84	    const lexeme = match[0]; offset += lexeme.length;
85	    if (lexeme === "-0") fail("NEGATIVE_ZERO");
86	    if (text[offset] === "." || text[offset] === "e" || text[offset] === "E") fail("FLOAT_FORBIDDEN");
87	    // Reject overlong digits before allocating an unbounded BigInt.
88	    if (lexeme.length > 21) fail("INTEGER_RANGE");
89	    const number = BigInt(lexeme);
90	    if (number < MIN_INTEGER || number > MAX_INTEGER) fail("INTEGER_RANGE");
91	    return number;
92	  };
93	  const result = value(0); space();
94	  if (offset !== text.length) fail("TRAILING_DATA");
95	  return result;
96	}
