98	export function canonical(value: Json): Uint8Array {
99	  const chunks: string[] = []; let bytes = 0;
100	  const put = (part: string) => {
101	    bytes += encoder.encode(part).length;
102	    if (bytes > MAX_BYTES) fail("BYTE_LIMIT");
103	    chunks.push(part);
104	  };
105	  const visit = (item: Json, depth: number): void => {
106	    if (item === null) { put("null"); return; }
107	    if (typeof item === "boolean") { put(item ? "true" : "false"); return; }
108	    if (typeof item === "bigint") {
109	      if (item < MIN_INTEGER || item > MAX_INTEGER) fail("INTEGER_RANGE");
110	      put(item.toString()); return;
111	    }
112	    if (typeof item === "string") { scalarString(item); put(JSON.stringify(item)); return; }
113	    if (typeof item !== "object") fail("EXACT_JSON_TYPE_REQUIRED");
114	    if (depth >= MAX_DEPTH) fail("DEPTH_LIMIT");
115	    if (Array.isArray(item)) {
116	      if (Object.getOwnPropertySymbols(item).length || Object.getOwnPropertyNames(item).length !== item.length + 1) fail("PLAIN_ARRAY_REQUIRED");
117	      put("["); for (let i = 0; i < item.length; i++) {
118	        if (i) put(",");
119	        const descriptor = Object.getOwnPropertyDescriptor(item, String(i));
120	        if (!descriptor || !Object.hasOwn(descriptor, "value")) fail("ARRAY_DATA_PROPERTIES_REQUIRED");
121	        visit(descriptor!.value as Json, depth + 1);
122	      } put("]");
123	      return;
124	    }
125	    if (Object.getPrototypeOf(item) !== null && Object.getPrototypeOf(item) !== Object.prototype) fail("PLAIN_OBJECT_REQUIRED");
126	    if (Object.getOwnPropertySymbols(item).length) fail("STRING_KEY_REQUIRED");
127	    const keys = Object.keys(item).sort(utf8Compare);
128	    if (keys.length !== Object.getOwnPropertyNames(item).length) fail("ENUMERABLE_DATA_REQUIRED");
129	    put("{"); for (let i = 0; i < keys.length; i++) {
130	      if (i) put(","); const key = keys[i]!; scalarString(key);
131	      const descriptor = Object.getOwnPropertyDescriptor(item, key)!;
132	      if (!Object.hasOwn(descriptor, "value")) fail("DATA_PROPERTIES_REQUIRED");
133	      put(JSON.stringify(key)); put(":"); visit(descriptor.value as Json, depth + 1);
134	    } put("}");
135	  };
136	  visit(value, 0); return encoder.encode(chunks.join(""));
137	}
