1	/** Trial interpreter for the selected schema vocabulary. Shape is not semantic authority. */
2	import { canonical, parseExact, type Json, utf8Compare } from "./exact-json.js";
3	type ObjectValue = { [key: string]: Json };
4	const object = (v: Json | undefined): v is ObjectValue => v !== null && typeof v === "object" && !Array.isArray(v);
5	const equal = (a: Json, b: Json): boolean => {
6	  if (typeof a !== typeof b) return false;
7	  if (a === b) return true;
8	  if (Array.isArray(a)) return Array.isArray(b) && a.length === b.length && a.every((v, i) => equal(v, b[i]!));
9	  if (!object(a) || !object(b)) return false;
10	  const keys = Object.keys(a);
11	  return keys.length === Object.keys(b).length && keys.every(k => Object.hasOwn(b, k) && equal(a[k]!, b[k]!));
12	};
13	export class SchemaError extends Error {}
14	export class ShapeLimit extends Error {}
15	const known = new Set(["$id", "$schema", "$defs", "definitions", "$ref", "title", "description", "default", "type", "const", "enum", "allOf", "anyOf", "oneOf", "not", "if", "then", "else", "properties", "patternProperties", "additionalProperties", "propertyNames", "required", "minProperties", "maxProperties", "items", "minItems", "maxItems", "uniqueItems", "contains", "minLength", "maxLength", "pattern", "minimum", "maximum", "x-opensip-order"]);
