21	export class SchemaRegistry {
22	  private readonly documents = new Map<string, Json>();
23	  private readonly patterns = new Map<string, RegExp>();
24	  private readonly checkedRefs = new Set<string>();
25	  constructor(documents: readonly Json[]) {
26	    for (const document of documents) {
27	      const owned = parseExact(canonical(document));
28	      if (!object(owned) || typeof owned.$id !== "string" || this.documents.has(owned.$id)) throw new SchemaError("duplicate or missing schema ID");
29	      if (owned.$schema !== "https://json-schema.org/draft/2020-12/schema") throw new SchemaError("unsupported schema dialect");
30	      this.documents.set(owned.$id, owned);
31	    }
32	  }
33	  private regex(pattern: string): RegExp {
34	    let result = this.patterns.get(pattern);
35	    if (!result) { result = new RegExp(pattern, "u"); this.patterns.set(pattern, result); }
36	    return result;
37	  }
38	  private resolve(ref: string, owner: string): [Json, string] {
39	    const split = ref.indexOf("#");
40	    const id = (split < 0 ? ref : ref.slice(0, split)) || owner;
41	    const fragment = split < 0 ? "" : ref.slice(split + 1);
42	    let value = this.documents.get(id);
43	    if (value === undefined) throw new SchemaError("unregistered schema ID: " + id);
44	    if (fragment && !fragment.startsWith("/")) throw new SchemaError("unsupported reference anchor");
45	    for (const segment of fragment.split("/").slice(1)) {
46	      const key = segment.replaceAll("~1", "/").replaceAll("~0", "~");
47	      if (!object(value) || !Object.hasOwn(value, key)) throw new SchemaError("missing schema pointer: " + ref);
48	      value = value[key]!;
49	    }
50	    if (typeof value !== "boolean" && !object(value)) throw new SchemaError("reference does not select a schema");
51	    return [value, id];
52	  }
